import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Appearance & Themes","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Theme Modes","slug":"_1-theme-modes","link":"#_1-theme-modes","children":[]},{"level":2,"title":"2. Theme Selection Cards","slug":"_2-theme-selection-cards","link":"#_2-theme-selection-cards","children":[{"level":3,"title":"Built-in & Bundled Themes","slug":"built-in-bundled-themes","link":"#built-in-bundled-themes","children":[]},{"level":3,"title":"Plugin Theme Extensibility","slug":"plugin-theme-extensibility","link":"#plugin-theme-extensibility","children":[]}]}],"relativePath":"user-guide/settings/appearance.md","filePath":"user-guide/settings/appearance.md","lastUpdated":1791112464000}`),a={name:`user-guide/settings/appearance.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="appearance-themes" tabindex="-1">Appearance &amp; Themes <a class="header-anchor" href="#appearance-themes" aria-label="Permalink to “Appearance &amp; Themes”">​</a></h1><p>Lertaro supports theme mode switching and multiple color palettes. The Appearance settings page is docked near the bottom of the left sidebar (just above &quot;About&quot;).</p><h2 id="_1-theme-modes" tabindex="-1">1. Theme Modes <a class="header-anchor" href="#_1-theme-modes" aria-label="Permalink to “1. Theme Modes”">​</a></h2><p>Three mode selection cards are displayed at the top of the page:</p><ul><li><strong>Light Mode</strong>: Locks the interface to a bright aesthetic; the theme selector grid displays only light-themed cards.</li><li><strong>Dark Mode</strong>: Locks the interface to a sleek dark aesthetic; the grid displays only dark-themed cards.</li><li><strong>Follow System</strong>: Automatically switches between two user-specified themes as Windows toggles between light and dark modes. In this mode, the grid splits into <strong>Light Theme</strong> and <strong>Dark Theme</strong> selectors, allowing you to choose distinct palettes for day and night without requiring application restarts.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Lertaro independently remembers your chosen theme for both light and dark styles, preserving your selections when toggling modes.</p></div><h2 id="_2-theme-selection-cards" tabindex="-1">2. Theme Selection Cards <a class="header-anchor" href="#_2-theme-selection-cards" aria-label="Permalink to “2. Theme Selection Cards”">​</a></h2><p>Themes are presented in an interactive card grid. Each card renders an accurate mini preview of the search bar, shadow borders, typography hierarchy, and highlighted result row colors. The active theme is marked with a checkmark badge.</p><h3 id="built-in-bundled-themes" tabindex="-1">Built-in &amp; Bundled Themes <a class="header-anchor" href="#built-in-bundled-themes" aria-label="Permalink to “Built-in &amp; Bundled Themes”">​</a></h3><ul><li><strong>Core Built-in Themes (CoreExtensions)</strong>: <ul><li><strong>Light</strong> / <strong>Dark</strong>: Clean and minimalistic designs that integrate with native Windows styling.</li><li><strong>Nordic Blue</strong>: Cool-toned geek aesthetic featuring soft ice-blue accents against a deep navy backdrop.</li><li><strong>Sakura Pink</strong>: Gentle, refreshing pastel rose and white palette.</li><li><strong>Cyberpunk</strong>: High-contrast neon yellow and midnight purple for a futuristic flair.</li></ul></li><li><strong>Anime Themes (AnimeThemes, Bundled)</strong>: <ul><li><strong>Evangelion</strong>, <strong>Sakura Blossom</strong>, and <strong>Weathering with You</strong>.</li></ul></li><li><strong>Curated Theme Pairs (Curated Themes, Bundled)</strong>: <ul><li>20 paired light/dark palettes: <strong>Glacier</strong>, <strong>Terracotta</strong>, <strong>Forest</strong>, <strong>Amethyst</strong>, <strong>Crimson</strong>, <strong>Graphite</strong>, <strong>Indigo</strong>, <strong>Mint</strong>, <strong>Champagne</strong>, <strong>Amber</strong>, <strong>Rosé</strong>, <strong>Ocean Teal</strong>, <strong>Matcha</strong>, <strong>Mocha</strong>, <strong>Obsidian</strong>, <strong>Coral Sunset</strong>, <strong>Lavender</strong>, <strong>Nordic Sage</strong>, <strong>Parchment Sepia</strong>, and <strong>Cobalt Blue</strong>.</li></ul></li></ul><h3 id="plugin-theme-extensibility" tabindex="-1">Plugin Theme Extensibility <a class="header-anchor" href="#plugin-theme-extensibility" aria-label="Permalink to “Plugin Theme Extensibility”">​</a></h3><p>All themes adhere to the standard UI theme specifications provided by <code>Lertaro.PluginSdk</code>. Third-party developers can create and distribute custom theme plugins to register new palettes in this grid.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};